import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"64、【未济】 坎下离上","description":"周易口诀义 - 64、【未济】 坎下离上","frontmatter":{"title":"64、【未济】 坎下离上","description":"周易口诀义 - 64、【未济】 坎下离上"},"headers":[],"relativePath":"zh/classics/koujueyi/066.md","filePath":"zh/classics/koujueyi/066.md"}'),r={name:"zh/classics/koujueyi/066.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_64、【未济】-坎下离上" tabindex="-1">64、【未济】 坎下离上 <a class="header-anchor" href="#_64、【未济】-坎下离上" aria-label="Permalink to “64、【未济】 坎下离上”">​</a></h1><p>彖曰：「未济亨」，柔得中也。「小狐汔济」，未出中也。「濡其尾，无攸利」，不续终也。虽不当位，刚柔应也。</p><p>象曰：火在水上，未济。君子以慎辨物居方。</p><p>初六：濡其尾，吝。</p><p>象曰：「濡其尾」，亦不知极也。</p><p>九二：曳其轮，贞吉。</p><p>象曰：九二贞吉，中以行正也。</p><p>六三：未济，征凶，利涉大川。</p><p>象曰：「未济征凶」，位不当也。</p><p>九四：贞吉悔亡。震用伐鬼方，三年有赏于大国。</p><p>象曰：「贞吉悔亡」，志行也。</p><p>六五，贞吉无悔，君子之光，有孚吉。</p><p>象曰：「君子之光」，其晖吉也。</p><p>上九，有孚于饮酒，无咎。濡其首，有孚失是。</p><p>象曰：饮酒濡首，亦不知节也。</p><p>解读</p><p>「未济，亨」者，未济是未能济渡之名，喻人德薄居位，才德劣小，不能拔济危难，必须任之于贤，委之于德，则有可济之理，故曰</p><p>「未济亨」也。「小狐汔济，濡其尾，无攸利」者，汔，将尽之名，其犹小才之人，不能济拔险难，譬之小狐渡水，智力羸劣，必须待水乾浅方可涉川，未及于岸，力已疲惫，遂濡湿其尾，几至没溺，岂有利焉？故曰「濡其尾，无攸利」也。</p><p>象曰「火在水上，未济」者，夫水火之用，相合而成，即能济人之性命。今火居其上而上炎，水流于下而下注，火水各抗，焉能烹饪？故为未济也。「君子以慎辨物居方」者，君子见未济之患，以谨慎为用，故分辨事物，各安其居也。</p><p>「初六，濡其尾，吝」者，初六处未济之初，最居险下，而欲强进求济，其如力薄何？所以进未达岸，濡湿其尾，故曰「濡其尾」也。然体虽阴柔，不为刚狠之性，而乃犹不思反，以斯而往，顽亦甚矣，故曰「吝」也。</p><p>「九二，曳其轮，贞吉」者，九二以刚居中，而应于五，为君委任，即是救难之人。然二虽处险中，不为难之所溺，故经纶屯蹇，任重忧深，所以曳拔其轮，以出险外，故曰「曳其轮」也。救难济危，莫过于正，故曰「贞吉」也。</p><p>「六三，未济，征凶，利涉大川」者，六三处未济之时，以阴柔之质，失位之正，安能自济？若征而求济，必致凶危，故曰「未济，征凶」也。然九二刚阳，为君委任，即是能救难之人；六三若能委质亲二，即不虑没溺，自然获济，故曰「利涉大川」也。</p><p>「九四，贞吉，悔亡，震用伐鬼方，三年有赏于大国」者，九四履失其位，所以有悔。然出险难之外，居文明之初，接近于君，志行其正，所以获吉，忧悔乃亡，故曰「贞吉，悔亡」也。为君所任，正志既行，靡有禁其威者，故震发威怒，以伐远方，故曰「震用伐鬼方」。鬼方者，兴衰之征也，每至兴衰取义焉。四方文明之初，其德未盛，不能即服，故曰「三年」也。五处中位，体包明德，既居尊位，不夺物功，九四既有功劳，而乃以百里之国赏之，谓封以茅土，故曰「有赏于大国」也。</p><p>「六五，贞吉，无悔。君子之光，有孚，吉」者，以柔居尊，所以有悔。然以文明之质，为未济之主，故必贞正，所以获吉，忧悔乃亡，故曰「贞吉，无悔」也。以文明之质，居于尊位，不自任察，而委于二，是使武以文，御刚以柔，故有君子之光辉也。委其权于有能之人，而心不疑，则人皆竭其诚信，功劳克济，故曰「有孚吉」也。</p><p>上九，有孚于饮酒，无咎。「濡其首，有孚失是」者，处未济之极，即入于既济，既得济矣，任人又当，心即无疑，信任得人，自取逸乐，饮酒而已，不虑危咎，故曰「有孚于饮酒，无咎」也。饮酒不节，乐过淫荒，所以濡首之难，还复及之，故曰「濡其首」也。所以濡首之难及之者，良由信任于人，不忧祸患，失于所是，故曰「有孚失是」。</p>',25)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
